"""Event construction, validation and canonical encoding."""

import json
import math
import re

from .errors import ValidationError

OPS = ("create", "update", "delete")
EVENT_KEYS = frozenset(("seq", "entity_id", "op", "payload"))
MAX_SEQ = 1000000000
MAX_STR = 200
MAX_LIST = 32

_ENTITY_RE = re.compile(r"^[a-z0-9][a-z0-9_-]{0,63}$")
_FIELD_RE = re.compile(r"^[a-z][a-z0-9_]{0,31}$")


def check_seq(seq):
    """Validate and return an event sequence number."""
    if isinstance(seq, bool) or not isinstance(seq, int):
        raise ValidationError("seq must be an int")
    if seq < 1 or seq > MAX_SEQ:
        raise ValidationError("seq out of range: %r" % (seq,))
    return seq


def check_entity_id(entity_id):
    """Validate and return an entity id."""
    if not isinstance(entity_id, str) or _ENTITY_RE.match(entity_id) is None:
        raise ValidationError("invalid entity_id: %r" % (entity_id,))
    return entity_id


def _check_scalar(value):
    if value is None or isinstance(value, bool) or isinstance(value, int):
        return value
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValidationError("float values must be finite")
        return value
    if isinstance(value, str):
        if len(value) > MAX_STR:
            raise ValidationError("string value too long")
        return value
    raise ValidationError("unsupported payload value: %r" % (type(value),))


def check_payload(payload):
    """Validate a payload and return an independent plain dict copy."""
    if payload is None:
        return {}
    if not isinstance(payload, dict):
        raise ValidationError("payload must be a dict or None")
    out = {}
    for key, value in payload.items():
        if not isinstance(key, str) or _FIELD_RE.match(key) is None:
            raise ValidationError("invalid payload key: %r" % (key,))
        if isinstance(value, list):
            if len(value) > MAX_LIST:
                raise ValidationError("list value too long")
            out[key] = [_check_scalar(item) for item in value]
        else:
            out[key] = _check_scalar(value)
    return out


def make_event(seq, entity_id, op, payload=None):
    """Build a validated, fully isolated event dict."""
    check_seq(seq)
    check_entity_id(entity_id)
    if not isinstance(op, str) or op not in OPS:
        raise ValidationError("invalid op: %r" % (op,))
    fields = check_payload(payload)
    if op == "delete" and fields:
        raise ValidationError("delete events must carry an empty payload")
    return {"seq": seq, "entity_id": entity_id, "op": op, "payload": fields}


def normalize_event(event):
    """Validate a raw event mapping and return a normalized copy."""
    if not isinstance(event, dict):
        raise ValidationError("event must be a dict")
    if frozenset(event) != EVENT_KEYS:
        raise ValidationError("event keys must be exactly %s"
                              % (sorted(EVENT_KEYS),))
    return make_event(event["seq"], event["entity_id"], event["op"],
                      event["payload"])


def canonical_form(event):
    """Return the canonical JSON encoding used for duplicate detection."""
    return json.dumps(normalize_event(event), sort_keys=True,
                      separators=(",", ":"))

