"""In-memory projection of a versioned event stream."""

import copy

from .errors import ConflictError, NotFoundError, SequenceError, ValidationError
from .events import canonical_form, check_entity_id, normalize_event

RECORD_KEYS = frozenset(("entity_id", "version", "seq", "updated_at",
                         "deleted", "fields"))


def default_clock():
    """Clock used when none is injected."""
    return 0


def _check_flag(value, name):
    if not isinstance(value, bool):
        raise ValidationError("%s must be a bool" % (name,))
    return value


def check_clock(clock):
    """Validate a clock argument and return the callable to use."""
    if clock is None:
        return default_clock
    if not callable(clock):
        raise ValidationError("clock must be callable or None")
    return clock


class Projection:
    """Projects create/update/delete events into versioned entity records."""

    def __init__(self, clock=None):
        self._clock = check_clock(clock)
        self._records = {}
        self._log = {}
        self._next_seq = 1
        self._last_updated_at = None

    # -- internals ---------------------------------------------------------

    def _restore(self, records, events, next_seq, last_updated_at):
        self._records = copy.deepcopy(records)
        self._log = {event["seq"]: copy.deepcopy(event) for event in events}
        self._next_seq = next_seq
        self._last_updated_at = last_updated_at

    def _tick(self):
        value = self._clock()
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValidationError("clock must return a non-negative int")
        return value

    def _project(self, event):
        """Return the record that `event` produces, without mutating state."""
        entity_id = event["entity_id"]
        op = event["op"]
        current = self._records.get(entity_id)
        if op == "create":
            if current is not None:
                raise ConflictError("entity already exists: %s" % (entity_id,))
            return {"entity_id": entity_id, "version": 1, "seq": 0,
                    "updated_at": 0, "deleted": False,
                    "fields": copy.deepcopy(event["payload"])}
        if current is None:
            raise NotFoundError("unknown entity: %s" % (entity_id,))
        if current["deleted"]:
            raise ConflictError("entity is deleted: %s" % (entity_id,))
        record = {"entity_id": entity_id, "version": current["version"] + 1,
                  "seq": 0, "updated_at": 0, "deleted": False, "fields": {}}
        if op == "delete":
            record["deleted"] = True
            return record
        fields = copy.deepcopy(current["fields"])
        for key, value in event["payload"].items():
            if value is None:
                fields.pop(key, None)
            else:
                fields[key] = copy.deepcopy(value)
        record["fields"] = fields
        return record

    def _state(self):
        return (copy.deepcopy(self._records), copy.deepcopy(self._log),
                self._next_seq, self._last_updated_at)

    def _set_state(self, state):
        self._records, self._log, self._next_seq, self._last_updated_at = state

    # -- public API --------------------------------------------------------

    def apply_event(self, event):
        """Apply one event; return True if state changed, False on replay."""
        normalized = normalize_event(event)
        seq = normalized["seq"]
        if seq > self._next_seq:
            raise SequenceError("sequence hole: expected %d, got %d"
                                % (self._next_seq, seq))
        if seq < self._next_seq:
            previous = self._log[seq]
            if canonical_form(previous) == canonical_form(normalized):
                return False
            raise ConflictError("event %d differs from the applied one" % seq)
        record = self._project(normalized)
        now = self._tick()
        record["seq"] = seq
        record["updated_at"] = now
        self._records[normalized["entity_id"]] = record
        self._log[seq] = normalized
        self._next_seq = seq + 1
        self._last_updated_at = now
        return True

    def apply_batch(self, events):
        """Apply a list/tuple of events atomically; return the applied count."""
        if not isinstance(events, (list, tuple)):
            raise ValidationError("events must be a list or a tuple")
        saved = self._state()
        applied = 0
        try:
            for event in events:
                if self.apply_event(event):
                    applied += 1
        except BaseException:
            self._set_state(saved)
            raise
        return applied

    def get(self, entity_id, include_deleted=False):
        """Return a deep copy of one record."""
        check_entity_id(entity_id)
        _check_flag(include_deleted, "include_deleted")
        record = self._records.get(entity_id)
        if record is None or (record["deleted"] and not include_deleted):
            raise NotFoundError("unknown entity: %s" % (entity_id,))
        return copy.deepcopy(record)

    def snapshot(self, include_deleted=False):
        """Return deep copies of the records, sorted by entity_id."""
        _check_flag(include_deleted, "include_deleted")
        rows = []
        for entity_id in sorted(self._records):
            record = self._records[entity_id]
            if record["deleted"] and not include_deleted:
                continue
            rows.append(copy.deepcopy(record))
        return rows

    def applied_events(self):
        """Return deep copies of the applied events, sorted by seq."""
        return [copy.deepcopy(self._log[seq]) for seq in sorted(self._log)]

    def stats(self):
        """Return a summary of the projection."""
        live = 0
        for record in self._records.values():
            if not record["deleted"]:
                live += 1
        return {"live": live, "deleted": len(self._records) - live,
                "applied": len(self._log), "next_seq": self._next_seq,
                "last_updated_at": self._last_updated_at}

gold_files.eventview/journal.py:
"""Deterministic JSON persistence for projections."""

import json
import os

from .errors import NotFoundError, ValidationError
from .events import MAX_SEQ, check_entity_id, check_payload, normalize_event
from .projection import RECORD_KEYS, Projection

FORMAT = "eventview/1"
DOC_KEYS = frozenset(("format", "next_seq", "last_updated_at", "records",
                      "events"))


def _check_path(path):
    if not isinstance(path, str) or not path:
        raise ValidationError("path must be a non-empty str")
    return path


def _check_index(value, name, low, high):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValidationError("%s must be an int" % (name,))
    if value < low or value > high:
        raise ValidationError("%s out of range: %r" % (name, value))
    return value


def _check_record(item, next_seq):
    if not isinstance(item, dict) or frozenset(item) != RECORD_KEYS:
        raise ValidationError("record keys must be exactly %s"
                              % (sorted(RECORD_KEYS),))
    entity_id = check_entity_id(item["entity_id"])
    version = _check_index(item["version"], "version", 1, MAX_SEQ)
    seq = _check_index(item["seq"], "seq", 1, next_seq - 1)
    updated_at = _check_index(item["updated_at"], "updated_at", 0, MAX_SEQ)
    deleted = item["deleted"]
    if not isinstance(deleted, bool):
        raise ValidationError("deleted must be a bool")
    if not isinstance(item["fields"], dict):
        raise ValidationError("fields must be a dict")
    fields = check_payload(item["fields"])
    if deleted and fields:
        raise ValidationError("tombstones must have empty fields")
    return {"entity_id": entity_id, "version": version, "seq": seq,
            "updated_at": updated_at, "deleted": deleted, "fields": fields}


def dump(projection, path):
    """Write a projection snapshot as canonical JSON; return byte count."""
    if not isinstance(projection, Projection):
        raise ValidationError("projection must be a Projection")
    _check_path(path)
    stats = projection.stats()
    doc = {"format": FORMAT,
           "next_seq": stats["next_seq"],
           "last_updated_at": stats["last_updated_at"],
           "records": projection.snapshot(include_deleted=True),
           "events": projection.applied_events()}
    data = (json.dumps(doc, sort_keys=True, indent=2) + "\n").encode("utf-8")
    with open(path, "wb") as handle:
        handle.write(data)
    return len(data)


def load(path, clock=None):
    """Read a snapshot written by `dump` and return a new Projection."""
    _check_path(path)
    if not os.path.isfile(path):
        raise NotFoundError("no such snapshot: %s" % (path,))
    with open(path, "rb") as handle:
        raw = handle.read()
    try:
        doc = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError):
        raise ValidationError("snapshot is not valid JSON")
    if not isinstance(doc, dict) or frozenset(doc) != DOC_KEYS:
        raise ValidationError("snapshot keys must be exactly %s"
                              % (sorted(DOC_KEYS),))
    if doc["format"] != FORMAT:
        raise ValidationError("unsupported snapshot format")
    next_seq = _check_index(doc["next_seq"], "next_seq", 1, MAX_SEQ + 1)
    last_updated_at = doc["last_updated_at"]
    if last_updated_at is not None:
        _check_index(last_updated_at, "last_updated_at", 0, MAX_SEQ)
    if not isinstance(doc["events"], list):
        raise ValidationError("events must be a list")
    if not isinstance(doc["records"], list):
        raise ValidationError("records must be a list")
    events = [normalize_event(item) for item in doc["events"]]
    if [event["seq"] for event in events] != list(range(1, next_seq)):
        raise ValidationError("stored events do not cover 1..next_seq-1")
    records = {}
    for item in doc["records"]:
        record = _check_record(item, next_seq)
        if record["entity_id"] in records:
            raise ValidationError("duplicate record: %s"
                                  % (record["entity_id"],))
        records[record["entity_id"]] = record
    projection = Projection(clock=clock)
    projection._restore(records, events, next_seq, last_updated_at)
    return projection

