        """Return the record that `event` produces, without mutating state."""
        entity_id = event["entity_id"]
        op = event["op"]
        current = self._records.get(entity_id)
        if op == "create":
            if current is not None:
                raise ConflictError("entity already exists: %s" % (entity_id,))
            return {"entity_id": entity_id, "version": 1, "seq": 0,
                    "updated_at": 0, "deleted": False,
                    "fields": copy.deepcopy(event["payload"])}
        if current is None:
            raise NotFoundError("unknown entity: %s" % (entity_id,))
        if current["deleted"]:
            raise ConflictError("entity is deleted: %s" % (entity_id,))
        record = {"entity_id": entity_id, "version": current["version"] + 1,
                  "seq": 0, "updated_at": 0, "deleted": False, "fields": {}}
        if op == "delete":
            record["deleted"] = True
            return record
        fields = copy.deepcopy(current["fields"])
        for key, value in event["payload"].items():
            if value is None:
                fields.pop(key, None)
            else:
                fields[key] = copy.deepcopy(value)
        record["fields"] = fields
        return record

    def _state(self):
        return (copy.deepcopy(self._records), copy.deepcopy(self._log),
                self._next_seq, self._last_updated_at)

    def _set_state(self, state):
        self._records, self._log, self._next_seq, self._last_updated_at = state

    # -- public API --------------------------------------------------------

    def apply_event(self, event):
        """Apply one event; return True if state changed, False on replay."""
        normalized = normalize_event(event)
        seq = normalized["seq"]
        if seq > self._next_seq:
            raise SequenceError("sequence hole: expected %d, got %d"
                                % (self._next_seq, seq))
        if seq < self._next_seq:
            previous = self._log[seq]
            if canonical_form(previous) == canonical_form(normalized):
                return False
            raise ConflictError("event %d differs from the applied one" % seq)
        record = self._project(normalized)
        now = self._tick()
        record["seq"] = seq
        record["updated_at"] = now
        self._records[normalized["entity_id"]] = record
        self._log[seq] = normalized
        self._next_seq = seq + 1
        self._last_updated_at = now
        return True

    def apply_batch(self, events):
        """Apply a list/tuple of events atomically; return the applied count."""
        if not isinstance(events, (list, tuple)):
            raise ValidationError("events must be a list or a tuple")
        saved = self._state()
        applied = 0
        try:
            for event in events:
                if self.apply_event(event):
                    applied += 1
        except BaseException:
            self._set_state(saved)
            raise
        return applied

    def get(self, entity_id, include_deleted=False):
        """Return a deep copy of one record."""
        check_entity_id(entity_id)
        _check_flag(include_deleted, "include_deleted")
        record = self._records.get(entity_id)
        if record is None or (record["deleted"] and not include_deleted):
            raise NotFoundError("unknown entity: %s" % (entity_id,))
        return copy.deepcopy(record)

    def snapshot(self, include_deleted=False):
        """Return deep copies of the records, sorted by entity_id."""
        _check_flag(include_deleted, "include_deleted")
        rows = []
        for entity_id in sorted(self._records):
            record = self._records[entity_id]
            if record["deleted"] and not include_deleted:
                continue
            rows.append(copy.deepcopy(record))
        return rows

    def applied_events(self):
        """Return deep copies of the applied events, sorted by seq."""
        return [copy.deepcopy(self._log[seq]) for seq in sorted(self._log)]

    def stats(self):
        """Return a summary of the projection."""
        live = 0
        for record in self._records.values():
            if not record["deleted"]:
                live += 1
        return {"live": live, "deleted": len(self._records) - live,
                "applied": len(self._log), "next_seq": self._next_seq,
                "last_updated_at": self._last_updated_at}

