"""Deterministic JSON persistence for projections."""

import json
import os

from .errors import NotFoundError, ValidationError
from .events import MAX_SEQ, check_entity_id, check_payload, normalize_event
from .projection import RECORD_KEYS, Projection

FORMAT = "eventview/1"
DOC_KEYS = frozenset(("format", "next_seq", "last_updated_at", "records",
                      "events"))


def _check_path(path):
    if not isinstance(path, str) or not path:
        raise ValidationError("path must be a non-empty str")
    return path


def _check_index(value, name, low, high):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValidationError("%s must be an int" % (name,))
    if value < low or value > high:
        raise ValidationError("%s out of range: %r" % (name, value))
    return value


def _check_record(item, next_seq):
    if not isinstance(item, dict) or frozenset(item) != RECORD_KEYS:
        raise ValidationError("record keys must be exactly %s"
                              % (sorted(RECORD_KEYS),))
    entity_id = check_entity_id(item["entity_id"])
    version = _check_index(item["version"], "version", 1, MAX_SEQ)
    seq = _check_index(item["seq"], "seq", 1, next_seq - 1)
    updated_at = _check_index(item["updated_at"], "updated_at", 0, MAX_SEQ)
    deleted = item["deleted"]
    if not isinstance(deleted, bool):
        raise ValidationError("deleted must be a bool")
    if not isinstance(item["fields"], dict):
        raise ValidationError("fields must be a dict")
    fields = check_payload(item["fields"])
    if deleted and fields:
        raise ValidationError("tombstones must have empty fields")
    return {"entity_id": entity_id, "version": version, "seq": seq,
            "updated_at": updated_at, "deleted": deleted, "fields": fields}


def dump(projection, path):
    """Write a projection snapshot as canonical JSON; return byte count."""
    if not isinstance(projection, Projection):
        raise ValidationError("projection must be a Projection")
    _check_path(path)
    stats = projection.stats()
    doc = {"format": FORMAT,
           "next_seq": stats["next_seq"],
           "last_updated_at": stats["last_updated_at"],
           "records": projection.snapshot(include_deleted=True),
           "events": projection.applied_events()}
    data = (json.dumps(doc, sort_keys=True, indent=2) + "\n").encode("utf-8")
    with open(path, "wb") as handle:
        handle.write(data)
    return len(data)


def load(path, clock=None):
    """Read a snapshot written by `dump` and return a new Projection."""
    _check_path(path)
    if not os.path.isfile(path):
        raise NotFoundError("no such snapshot: %s" % (path,))
    with open(path, "rb") as handle:
        raw = handle.read()
    try:
        doc = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError):
        raise ValidationError("snapshot is not valid JSON")
    if not isinstance(doc, dict) or frozenset(doc) != DOC_KEYS:
        raise ValidationError("snapshot keys must be exactly %s"
                              % (sorted(DOC_KEYS),))
    if doc["format"] != FORMAT:
        raise ValidationError("unsupported snapshot format")
    next_seq = _check_index(doc["next_seq"], "next_seq", 1, MAX_SEQ + 1)
    last_updated_at = doc["last_updated_at"]
    if last_updated_at is not None:
        _check_index(last_updated_at, "last_updated_at", 0, MAX_SEQ)
    if not isinstance(doc["events"], list):
        raise ValidationError("events must be a list")
    if not isinstance(doc["records"], list):
        raise ValidationError("records must be a list")
    events = [normalize_event(item) for item in doc["events"]]
    if [event["seq"] for event in events] != list(range(1, next_seq)):
        raise ValidationError("stored events do not cover 1..next_seq-1")
    records = {}
    for item in doc["records"]:
        record = _check_record(item, next_seq)
        if record["entity_id"] in records:
            raise ValidationError("duplicate record: %s"
                                  % (record["entity_id"],))
        records[record["entity_id"]] = record
    projection = Projection(clock=clock)
    projection._restore(records, events, next_seq, last_updated_at)
    return projection

