"""Opaque, snapshot-bound cursor tokens."""

import base64
import hashlib
import json

from pageerrors import InvalidCursorError

__all__ = ["encode_cursor", "decode_cursor"]

PREFIX = "v1"
_ALPHABET = frozenset(
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"
)


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _signature(body):
    return hashlib.sha256((PREFIX + "." + body).encode("ascii")).hexdigest()[:8]


def encode_cursor(version, rank, key):
    """Return the opaque token for the position (rank, key) in `version`."""
    if not _is_int(version):
        raise TypeError("version must be an int")
    if version < 0:
        raise ValueError("version must be non-negative")
    if not _is_int(rank):
        raise TypeError("rank must be an int")
    if not isinstance(key, str):
        raise TypeError("key must be a str")
    if key == "":
        raise ValueError("key must be non-empty")
    raw = json.dumps(
        {"k": key, "r": rank, "v": version}, sort_keys=True, separators=(",", ":")
    ).encode("utf-8")
    body = base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")
    return PREFIX + "." + body + "." + _signature(body)


def decode_cursor(token):
    """Return (version, rank, key) for a valid token."""
    if not isinstance(token, str):
        raise TypeError("token must be a str")
    parts = token.split(".")
    if len(parts) != 3:
        raise InvalidCursorError("cursor must have three segments")
    if parts[0] != PREFIX:
        raise InvalidCursorError("unknown cursor prefix")
    body, sig = parts[1], parts[2]
    if not body or not set(body) <= _ALPHABET:
        raise InvalidCursorError("cursor body is not url-safe base64")
    if sig != _signature(body):
        raise InvalidCursorError("cursor signature mismatch")
    try:
        raw = base64.urlsafe_b64decode((body + "=" * (-len(body) % 4)).encode("ascii"))
        payload = json.loads(raw.decode("utf-8"))
    except Exception as exc:
        raise InvalidCursorError("cursor body is not decodable") from exc
    if not isinstance(payload, dict) or set(payload) != {"k", "r", "v"}:
        raise InvalidCursorError("cursor payload has unexpected keys")
    version, rank, key = payload["v"], payload["r"], payload["k"]
    if not _is_int(version) or version < 0:
        raise InvalidCursorError("cursor version is invalid")
    if not _is_int(rank):
        raise InvalidCursorError("cursor rank is invalid")
    if not isinstance(key, str) or key == "":
        raise InvalidCursorError("cursor key is invalid")
    return (version, rank, key)

