    body, sig = parts[1], parts[2]
    if not body or not set(body) <= _ALPHABET:
        raise InvalidCursorError("cursor body is not url-safe base64")
    if sig != _signature(body):
        raise InvalidCursorError("cursor signature mismatch")
    try:
        raw = base64.urlsafe_b64decode((body + "=" * (-len(body) % 4)).encode("ascii"))
        payload = json.loads(raw.decode("utf-8"))
    except Exception as exc:
        raise InvalidCursorError("cursor body is not decodable") from exc
    if not isinstance(payload, dict) or set(payload) != {"k", "r", "v"}:
        raise InvalidCursorError("cursor payload has unexpected keys")
    version, rank, key = payload["v"], payload["r"], payload["k"]
    if not _is_int(version) or version < 0:
        raise InvalidCursorError("cursor version is invalid")
    if not _is_int(rank):
        raise InvalidCursorError("cursor rank is invalid")
    if not isinstance(key, str) or key == "":
        raise InvalidCursorError("cursor key is invalid")
    return (version, rank, key)

