"""Versioned in-memory records with immutable snapshots."""

from dataclasses import dataclass

__all__ = ["Record", "Snapshot", "RecordStore"]


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _check_key(key):
    if not isinstance(key, str):
        raise TypeError("key must be a str")
    if key == "":
        raise ValueError("key must be non-empty")
    return key


def _normalise_tags(tags):
    if isinstance(tags, (str, bytes, bytearray)):
        raise TypeError("tags must be a non-string iterable of str")
    try:
        values = list(tags)
    except TypeError as exc:
        raise TypeError("tags must be iterable") from exc
    for item in values:
        if not isinstance(item, str):
            raise TypeError("each tag must be a str")
    for item in values:
        if item == "":
            raise ValueError("each tag must be non-empty")
    return tuple(sorted(set(values)))


@dataclass(frozen=True)
class Record:
    key: str
    rank: int
    tags: tuple
    updated_at: int


@dataclass(frozen=True)
class Snapshot:
    version: int
    records: tuple


class RecordStore:
    """Holds records under unique string keys, with a monotonic version."""

    def __init__(self, clock):
        if not callable(clock):
            raise TypeError("clock must be callable")
        self._clock = clock
        self._records = {}
        self._version = 0

    @property
    def version(self):
        return self._version

    def put(self, key, rank, tags=()):
        _check_key(key)
        if not _is_int(rank):
            raise TypeError("rank must be an int")
        normalised = _normalise_tags(tags)
        stamp = self._clock()
        if not _is_int(stamp):
            raise TypeError("clock must return an int")
        record = Record(key=key, rank=rank, tags=normalised, updated_at=stamp)
        self._records[key] = record
        self._version += 1
        return record

    def remove(self, key):
        _check_key(key)
        if key not in self._records:
            raise KeyError(key)
        record = self._records.pop(key)
        self._version += 1
        return record

    def get(self, key):
        _check_key(key)
        return self._records.get(key)

    def snapshot(self):
        ordered = tuple(
            sorted(self._records.values(), key=lambda r: (r.rank, r.key))
        )
        return Snapshot(version=self._version, records=ordered)

