"""Stable cursor pagination over immutable snapshots."""

from dataclasses import dataclass

from cursorcodec import decode_cursor, encode_cursor
from pageerrors import StaleCursorError
from recordstore import Snapshot

__all__ = ["Page", "paginate", "MAX_LIMIT"]

MAX_LIMIT = 100


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


@dataclass(frozen=True)
class Page:
    items: tuple
    total: int
    has_prev: bool
    has_next: bool
    prev_cursor: object
    next_cursor: object


def _position(token, version):
    payload = decode_cursor(token)
    if payload[0] != version:
        raise StaleCursorError("cursor belongs to snapshot version %r" % (payload[0],))
    return (payload[1], payload[2])


def _validate(snapshot, limit, after, before, tag, min_rank, max_rank):
    if not isinstance(snapshot, Snapshot):
        raise TypeError("snapshot must be a Snapshot")
    if not _is_int(limit):
        raise TypeError("limit must be an int")
    if limit < 1 or limit > MAX_LIMIT:
        raise ValueError("limit must be between 1 and %d" % MAX_LIMIT)
    if after is not None and not isinstance(after, str):
        raise TypeError("after must be a str or None")
    if before is not None and not isinstance(before, str):
        raise TypeError("before must be a str or None")
    if after is not None and before is not None:
        raise ValueError("after and before are mutually exclusive")
    if tag is not None:
        if not isinstance(tag, str):
            raise TypeError("tag must be a str or None")
        if tag == "":
            raise ValueError("tag must be non-empty")
    if min_rank is not None and not _is_int(min_rank):
        raise TypeError("min_rank must be an int or None")
    if max_rank is not None and not _is_int(max_rank):
        raise TypeError("max_rank must be an int or None")
    if min_rank is not None and max_rank is not None and min_rank > max_rank:
        raise ValueError("min_rank must not exceed max_rank")


def paginate(snapshot, *, limit, after=None, before=None, tag=None,
             min_rank=None, max_rank=None):
    """Return one stable `Page` of the snapshot."""
    _validate(snapshot, limit, after, before, tag, min_rank, max_rank)

    matched = [
        record
        for record in snapshot.records
        if (tag is None or tag in record.tags)
        and (min_rank is None or record.rank >= min_rank)
        and (max_rank is None or record.rank <= max_rank)
    ]
    matched.sort(key=lambda r: (r.rank, r.key))
    total = len(matched)

    if after is not None:
        position = _position(after, snapshot.version)
        low = sum(1 for r in matched if (r.rank, r.key) <= position)
        high = min(low + limit, total)
    elif before is not None:
        position = _position(before, snapshot.version)
        high = sum(1 for r in matched if (r.rank, r.key) < position)
        low = max(0, high - limit)
    else:
        low = 0
        high = min(limit, total)

    items = tuple(matched[low:high])
    has_prev = low > 0
    has_next = high < total
    prev_cursor = None
    next_cursor = None
    if items and has_prev:
        prev_cursor = encode_cursor(snapshot.version, items[0].rank, items[0].key)
    if items and has_next:
        next_cursor = encode_cursor(snapshot.version, items[-1].rank, items[-1].key)
    return Page(
        items=items,
        total=total,
        has_prev=has_prev,
        has_next=has_next,
        prev_cursor=prev_cursor,
        next_cursor=next_cursor,
    )

