SEPARATOR = "/"


def require_str(value, name):
    """Raise TypeError unless *value* is an exact ``str``."""
    if not isinstance(value, str):
        raise TypeError("%s must be a str, got %s" % (name, type(value).__name__))


def split_path(path):
