"""Compilation and matching of ordered path patterns."""

from pathnorm import SEPARATOR, require_str, split_path
from ruleerrors import PathTraversalError, PatternError

ESCAPE = "\\"
STAR = "*"
DOUBLE_STAR = "**"

_ANY_SEGMENTS = object()


def _tokenize(segment):
    """Turn a raw pattern segment into a tuple of ('lit', ch) / ('star',)."""
    tokens = []
    index = 0
    size = len(segment)
    while index < size:
        char = segment[index]
        if char == ESCAPE:
            if index + 1 >= size:
                raise PatternError("dangling escape in segment %r" % (segment,))
            following = segment[index + 1]
            if following not in (STAR, ESCAPE):
                raise PatternError("invalid escape %r in segment %r" % (following, segment))
            tokens.append(("lit", following))
            index += 2
            continue
        if char == STAR:
            if tokens and tokens[-1] == ("star",):
                raise PatternError("'**' is only allowed as a whole segment: %r" % (segment,))
            tokens.append(("star",))
            index += 1
            continue
        tokens.append(("lit", char))
        index += 1
    return tuple(tokens)


def _match_segment(tokens, text):
    """Greedy backtracking match of one segment; '*' never spans a separator."""
    token_index = 0
    text_index = 0
    star_token = -1
    star_text = 0
    while text_index < len(text):
        if token_index < len(tokens) and tokens[token_index] == ("lit", text[text_index]):
            token_index += 1
            text_index += 1
        elif token_index < len(tokens) and tokens[token_index] == ("star",):
            star_token = token_index
            star_text = text_index
            token_index += 1
        elif star_token >= 0:
            star_text += 1
            text_index = star_text
            token_index = star_token + 1
        else:
            return False
    while token_index < len(tokens) and tokens[token_index] == ("star",):
        token_index += 1
    return token_index == len(tokens)


def _match_all(compiled, segments, pattern_index, path_index, memo):
    key = (pattern_index, path_index)
    if key in memo:
        return memo[key]
    if pattern_index == len(compiled):
        result = path_index == len(segments)
    elif compiled[pattern_index] is _ANY_SEGMENTS:
        result = _match_all(compiled, segments, pattern_index + 1, path_index, memo)
        if not result and path_index < len(segments):
            result = _match_all(compiled, segments, pattern_index, path_index + 1, memo)
    else:
        result = (
            path_index < len(segments)
            and _match_segment(compiled[pattern_index], segments[path_index])
            and _match_all(compiled, segments, pattern_index + 1, path_index + 1, memo)
        )
    memo[key] = result
    return result


class Pattern(object):
    """An immutable compiled pattern."""

    __slots__ = ("source", "segments", "specificity", "_compiled")

    def __init__(self, source, segments, compiled, specificity):
        object.__setattr__(self, "source", source)
        object.__setattr__(self, "segments", segments)
        object.__setattr__(self, "specificity", specificity)
        object.__setattr__(self, "_compiled", compiled)

    def __setattr__(self, name, value):
        raise AttributeError("Pattern instances are immutable")

    def __delattr__(self, name):
        raise AttributeError("Pattern instances are immutable")

    def __repr__(self):
        return "Pattern(%r)" % (self.source,)

    def match(self, path):
        """Return True when *path* is matched by this pattern."""
        segments = split_path(path)
        return _match_all(self._compiled, segments, 0, 0, {})


def compile_pattern(pattern):
    """Compile *pattern* into a :class:`Pattern`."""
    require_str(pattern, "pattern")
    if "\x00" in pattern:
        raise PatternError("pattern must not contain a NUL character")
    raw_segments = []
    for raw in pattern.split(SEPARATOR):
        if raw == "" or raw == ".":
            continue
        if raw == "..":
            raise PathTraversalError("pattern escapes the root: %r" % (pattern,))
        raw_segments.append(raw)
    compiled = []
    literals = 0
    stars = 0
    doubles = 0
    for raw in raw_segments:
        if raw == DOUBLE_STAR:
            compiled.append(_ANY_SEGMENTS)
            doubles += 1
            continue
        tokens = _tokenize(raw)
        if any(token == ("star",) for token in tokens):
            stars += 1
        else:
            literals += 1
        compiled.append(tokens)
    specificity = 100 * literals + 10 * stars + doubles
    return Pattern(pattern, tuple(raw_segments), tuple(compiled), specificity)

