"""Ordered include/exclude rule evaluation with explanation metadata."""

from pathnorm import normalize_path, require_str
from patternmatch import compile_pattern

ACTIONS = ("include", "exclude")

EXPLANATION_KEYS = (
    "path",
    "allowed",
    "action",
    "rule_index",
    "label",
    "pattern",
    "priority",
    "specificity",
    "matched",
    "default_used",
)


def _check_action(action, name):
    require_str(action, name)
    if action not in ACTIONS:
        raise ValueError("%s must be 'include' or 'exclude', got %r" % (name, action))
    return action


class Rule(object):
    """An immutable include/exclude rule."""

    __slots__ = ("pattern", "action", "priority", "label", "compiled")

    def __init__(self, pattern, action, priority=0, label=None):
        compiled = compile_pattern(pattern)
        _check_action(action, "action")
        if isinstance(priority, bool) or not isinstance(priority, int):
            raise TypeError("priority must be an int, got %s" % (type(priority).__name__,))
        if label is not None and not isinstance(label, str):
            raise TypeError("label must be None or a str, got %s" % (type(label).__name__,))
        object.__setattr__(self, "pattern", pattern)
        object.__setattr__(self, "action", action)
        object.__setattr__(self, "priority", priority)
        object.__setattr__(self, "label", label)
        object.__setattr__(self, "compiled", compiled)

    def __setattr__(self, name, value):
        raise AttributeError("Rule instances are immutable")

    def __delattr__(self, name):
        raise AttributeError("Rule instances are immutable")

    def __repr__(self):
        return "Rule(%r, %r, priority=%r, label=%r)" % (
            self.pattern,
            self.action,
            self.priority,
            self.label,
        )

    def matches(self, path):
        return self.compiled.match(path)


class RuleSet(object):
    """An ordered collection of rules evaluated by priority then order."""

    def __init__(self, rules=(), default_action="exclude"):
        _check_action(default_action, "default_action")
        self._default_action = default_action
        self._rules = []
        self.extend(rules)

    @property
    def default_action(self):
        return self._default_action

    @property
    def rules(self):
        return tuple(self._rules)

    def __len__(self):
        return len(self._rules)

    def add(self, rule):
        if not isinstance(rule, Rule):
            raise TypeError("rule must be a Rule, got %s" % (type(rule).__name__,))
        self._rules.append(rule)
        return self

    def extend(self, rules):
        if isinstance(rules, (str, bytes)):
            raise TypeError("rules must be an iterable of Rule")
        try:
            candidates = list(rules)
        except TypeError:
            raise TypeError("rules must be an iterable of Rule")
        for candidate in candidates:
            if not isinstance(candidate, Rule):
                raise TypeError("rules must contain Rule instances, got %s" % (type(candidate).__name__,))
        self._rules.extend(candidates)
        return self

    def explain(self, path):
        """Return a fresh dict describing the decision for *path*."""
        normalized = normalize_path(path)
        matched = []
        winner = None
        for index, rule in enumerate(self._rules):
            if rule.compiled.match(normalized):
                matched.append(index)
                if winner is None or rule.priority >= self._rules[winner].priority:
                    winner = index
        if winner is None:
            action = self._default_action
            return {
                "path": normalized,
                "allowed": action == "include",
                "action": action,
                "rule_index": None,
                "label": None,
                "pattern": None,
                "priority": None,
                "specificity": None,
                "matched": (),
                "default_used": True,
            }
        rule = self._rules[winner]
        return {
            "path": normalized,
            "allowed": rule.action == "include",
            "action": rule.action,
            "rule_index": winner,
            "label": rule.label,
            "pattern": rule.pattern,
            "priority": rule.priority,
            "specificity": rule.compiled.specificity,
            "matched": tuple(matched),
            "default_used": False,
        }

    def allows(self, path):
        return self.explain(path)["allowed"]

    def filter(self, paths):
        """Return the allowed normalised paths in first-seen input order."""
        if isinstance(paths, (str, bytes)):
            raise TypeError("paths must be an iterable of str")
        try:
            candidates = list(paths)
        except TypeError:
            raise TypeError("paths must be an iterable of str")
        seen = set()
        kept = []
        for candidate in candidates:
            normalized = normalize_path(candidate)
            if normalized in seen:
                continue
            seen.add(normalized)
            if self.allows(normalized):
                kept.append(normalized)
        return tuple(kept)


class DecisionLog(object):
    """Records decisions with timestamps taken from an injected clock."""

    def __init__(self, clock):
        if not callable(clock):
            raise TypeError("clock must be callable")
        self._clock = clock
        self._entries = []

    def __len__(self):
        return len(self._entries)

    def record(self, ruleset, path):
        if not isinstance(ruleset, RuleSet):
            raise TypeError("ruleset must be a RuleSet, got %s" % (type(ruleset).__name__,))
        explanation = ruleset.explain(path)
        explanation["at"] = self._clock()
        self._entries.append(dict(explanation))
        return explanation

    def entries(self):
        return tuple(dict(entry) for entry in self._entries)

    def summary(self):
        counts = {"include": 0, "exclude": 0, "total": len(self._entries)}
        for entry in self._entries:
            counts[entry["action"]] += 1
        return counts

gold_files.ruleloader.py:
"""Parsing of the textual rule format into Rule objects."""

from pathnorm import require_str
from ruleengine import Rule
from ruleerrors import RuleError, RuleSyntaxError

COMMENT = "#"
FIELD_SEPARATOR = ":"
FIELD_COUNT = 4
STRIPPED = " \t"
DIGITS = "0123456789"


def _parse_priority(text, line_number):
    if text == "":
        return 0
    body = text[1:] if text[0] in "+-" else text
    if body == "" or any(char not in DIGITS for char in body):
        raise RuleSyntaxError("invalid priority %r" % (text,), line_number)
    return int(text)


def parse_rules(text):
    """Parse rule *text* and return a tuple of Rule objects in file order."""
    require_str(text, "text")
    rules = []
    for offset, line in enumerate(text.splitlines()):
        line_number = offset + 1
        stripped = line.strip(STRIPPED)
        if stripped == "" or stripped.startswith(COMMENT):
            continue
        fields = stripped.split(FIELD_SEPARATOR, FIELD_COUNT - 1)
        if len(fields) != FIELD_COUNT:
            raise RuleSyntaxError("expected %d fields" % (FIELD_COUNT,), line_number)
        action = fields[0].strip(STRIPPED)
        priority_text = fields[1].strip(STRIPPED)
        label_text = fields[2].strip(STRIPPED)
        pattern = fields[3]
        if action not in ("include", "exclude"):
            raise RuleSyntaxError("invalid action %r" % (action,), line_number)
        priority = _parse_priority(priority_text, line_number)
        label = label_text if label_text != "" else None
        try:
            rules.append(Rule(pattern, action, priority, label))
        except RuleSyntaxError:
            raise
        except RuleError as exc:
            raise RuleSyntaxError("invalid pattern %r: %s" % (pattern, exc), line_number)
    return tuple(rules)


def load_rules(path):
    """Read UTF-8 rule text from *path* and return a tuple of Rule objects."""
    require_str(path, "path")
    with open(path, "r", encoding="utf-8") as handle:
        return parse_rules(handle.read())

