from ledger_capacity import CapacityTable
from ledger_errors import ConflictError, UnknownReservationError, ValidationError
from ledger_ids import normalize_request_id, normalize_resource_id, normalize_units


class CapacityLedger:
    """Reservation ledger with snapshots and rollback."""

    def __init__(self, clock, limits=None):
        self._table = CapacityTable(limits)
        self._clock = clock
        self._records = {}
        self._snapshots = []

    def _allocated(self, resource_id):
        return sum(record["units"] for record in self._records.values()
                   if record["resource_id"] == resource_id)

    def reserve(self, request_id, resource_id, units):
        key = normalize_request_id(request_id)
        target = normalize_resource_id(resource_id)
        amount = normalize_units(units)
        tick = self._clock()
        record = {
            "request_id": key,
            "resource_id": target,
            "units": amount,
            "created_at": tick,
            "updated_at": tick,
            "status": "active",
        }
        self._records[key] = record
        return record

    def reserve_many(self, entries):
        created = []
        for entry in entries:
            created.append(self.reserve(entry["request_id"], entry["resource_id"],
                                        entry["units"]))
        return created

    def update(self, request_id, units):
        key = normalize_request_id(request_id)
        amount = normalize_units(units)
        record = self._records[key]
        record["units"] = amount
        record["updated_at"] = self._clock()
        return record

    def release(self, request_id):
        key = normalize_request_id(request_id)
        if key not in self._records:
            raise UnknownReservationError("unknown request: %r" % (key,))
        record = self._records.pop(key)
        record["status"] = "released"
        return record

    def set_limit(self, resource_id, capacity):
        self._table.set_limit(resource_id, capacity)

    def get(self, request_id):
        return self._records[normalize_request_id(request_id)]

    def has_request(self, request_id):
        return request_id in self._records

    def allocated(self, resource_id):
        return self._allocated(normalize_resource_id(resource_id))

    def totals(self):
        totals = {}
        for record in self._records.values():
            totals[record["resource_id"]] = (
                totals.get(record["resource_id"], 0) + record["units"])
        return totals

    def limits(self):
        return self._table.as_dict()

    def resource_ids(self):
        return self._table.resource_ids()

    def list_reservations(self, resource_id=None, include_released=False):
        records = []
        for record in self._records.values():
            if resource_id is not None and record["resource_id"] != resource_id:
                continue
            records.append(record)
        return records

    def snapshot(self):
        self._snapshots.append(dict(self._records))
        return len(self._snapshots)

    def rollback(self, token):
        if not self._snapshots:
            raise ValidationError("no snapshot to roll back to")
        self._records = self._snapshots.pop()

