"""Registry of per-resource capacity limits."""

from collections.abc import Mapping

from ledger_errors import UnknownResourceError, ValidationError
from ledger_ids import normalize_capacity, normalize_resource_id


class CapacityTable:
    """A validated, order independent map of resource id -> capacity limit."""

    def __init__(self, limits=None):
        self._limits = {}
        if limits is None:
            return
        if not isinstance(limits, Mapping):
            raise ValidationError(
                "limits must be a mapping or None, got %s" % type(limits).__name__)
        staged = {}
        for key, value in limits.items():
            resource_id = normalize_resource_id(key)
            capacity = normalize_capacity(value)
            if resource_id in staged:
                raise ValidationError("duplicate resource id: %r" % (resource_id,))
            staged[resource_id] = capacity
        self._limits = staged

    def __len__(self):
        return len(self._limits)

    def set_limit(self, resource_id, capacity):
        key = normalize_resource_id(resource_id)
        value = normalize_capacity(capacity)
        self._limits[key] = value
        return None

    def limit_of(self, resource_id):
        key = normalize_resource_id(resource_id)
        if key not in self._limits:
            raise UnknownResourceError("unknown resource: %r" % (key,))
        return self._limits[key]

    def has(self, resource_id):
        return normalize_resource_id(resource_id) in self._limits

    def remove(self, resource_id):
        key = normalize_resource_id(resource_id)
        if key not in self._limits:
            raise UnknownResourceError("unknown resource: %r" % (key,))
        del self._limits[key]
        return None

    def resource_ids(self):
        return tuple(sorted(self._limits))

    def as_dict(self):
        return dict(self._limits)

