"""The capacity reservation ledger."""

from collections.abc import Mapping

from ledger_capacity import CapacityTable
from ledger_errors import (
    CapacityError,
    ConflictError,
    UnknownReservationError,
    UnknownResourceError,
    ValidationError,
)
from ledger_ids import (
    normalize_capacity,
    normalize_request_id,
    normalize_resource_id,
    normalize_units,
)

ENTRY_KEYS = frozenset(("request_id", "resource_id", "units"))


class CapacityLedger:
    """Idempotent reservation ledger with snapshots and rollback."""

    def __init__(self, clock, limits=None):
        if not callable(clock):
            raise ValidationError("clock must be callable")
        self._table = CapacityTable(limits)
        self._clock = clock
        self._records = {}
        self._snapshots = []

    # -- internals ---------------------------------------------------
    def _tick(self):
        value = self._clock()
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValidationError("clock must return an int")
        return int(value)

    def _allocated(self, resource_id):
        total = 0
        for record in self._records.values():
            if record["status"] == "active" and record["resource_id"] == resource_id:
                total += record["units"]
        return total

    @staticmethod
    def _copy(record):
        return dict(record)

    def _require_resource(self, resource_id):
        if not self._table.has(resource_id):
            raise UnknownResourceError("unknown resource: %r" % (resource_id,))
        return resource_id

    @staticmethod
    def _matches(record, resource_id, units):
        return (record["status"] == "active"
                and record["resource_id"] == resource_id
                and record["units"] == units)

    # -- writes ------------------------------------------------------
    def reserve(self, request_id, resource_id, units):
        key = normalize_request_id(request_id)
        target = normalize_resource_id(resource_id)
        amount = normalize_units(units)
        self._require_resource(target)
        existing = self._records.get(key)
        if existing is not None:
            if self._matches(existing, target, amount):
                return self._copy(existing)
            raise ConflictError("request %r conflicts with the ledger" % (key,))
        if self._allocated(target) + amount > self._table.limit_of(target):
            raise CapacityError("resource %r cannot fit %d units" % (target, amount))
        tick = self._tick()
        record = {
            "request_id": key,
            "resource_id": target,
            "units": amount,
            "created_at": tick,
            "updated_at": tick,
            "status": "active",
        }
        self._records[key] = record
        return self._copy(record)

    def reserve_many(self, entries):
        if not isinstance(entries, (list, tuple)):
            raise ValidationError(
                "entries must be a list or tuple, got %s" % type(entries).__name__)
        staged = []
        for entry in entries:
            if not isinstance(entry, Mapping):
                raise ValidationError("each entry must be a mapping")
            if set(entry.keys()) != set(ENTRY_KEYS):
                raise ValidationError(
                    "entry keys must be exactly %s" % (sorted(ENTRY_KEYS),))
            staged.append((
                normalize_request_id(entry["request_id"]),
                normalize_resource_id(entry["resource_id"]),
                normalize_units(entry["units"]),
            ))
        seen = set()
        for key, _target, _amount in staged:
            if key in seen:
                raise ValidationError("duplicate request id in batch: %r" % (key,))
            seen.add(key)
        plan = []
        needed = {}
        for key, target, amount in staged:
            self._require_resource(target)
            existing = self._records.get(key)
            if existing is not None:
                if self._matches(existing, target, amount):
                    plan.append((False, key, target, amount))
                    continue
                raise ConflictError("request %r conflicts with the ledger" % (key,))
            needed[target] = needed.get(target, 0) + amount
            plan.append((True, key, target, amount))
        for target in sorted(needed):
            if self._allocated(target) + needed[target] > self._table.limit_of(target):
                raise CapacityError("resource %r cannot fit the batch" % (target,))
        if needed:
            tick = self._tick()
            for is_new, key, target, amount in plan:
                if not is_new:
                    continue
                self._records[key] = {
                    "request_id": key,
                    "resource_id": target,
                    "units": amount,
                    "created_at": tick,
                    "updated_at": tick,
                    "status": "active",
                }
        return tuple(self._copy(self._records[item[1]]) for item in plan)

    def update(self, request_id, units):
        key = normalize_request_id(request_id)
        amount = normalize_units(units)
        record = self._records.get(key)
        if record is None:
            raise UnknownReservationError("unknown request: %r" % (key,))
        if record["status"] != "active":
            raise ConflictError("request %r is already released" % (key,))
        if record["units"] == amount:
            return self._copy(record)
        target = record["resource_id"]
        projected = self._allocated(target) - record["units"] + amount
        if projected > self._table.limit_of(target):
            raise CapacityError("resource %r cannot fit %d units" % (target, amount))
        tick = self._tick()
        record["units"] = amount
        record["updated_at"] = tick
        return self._copy(record)

    def release(self, request_id):
        key = normalize_request_id(request_id)
        record = self._records.get(key)
        if record is None:
            raise UnknownReservationError("unknown request: %r" % (key,))
        if record["status"] != "active":
            raise ConflictError("request %r is already released" % (key,))
        tick = self._tick()
        record["status"] = "released"
        record["updated_at"] = tick
        return self._copy(record)

    def set_limit(self, resource_id, capacity):
        target = normalize_resource_id(resource_id)
        value = normalize_capacity(capacity)
        if self._table.has(target) and value < self._allocated(target):
            raise CapacityError(
                "limit %d is below the allocated amount for %r" % (value, target))
        self._table.set_limit(target, value)
        return None

    def remove_resource(self, resource_id):
        target = normalize_resource_id(resource_id)
        if not self._table.has(target):
            raise UnknownResourceError("unknown resource: %r" % (target,))
        if self._allocated(target) > 0:
            raise ConflictError("resource %r still has active reservations" % (target,))
        self._table.remove(target)
        return None

    # -- reads -------------------------------------------------------
    def get(self, request_id):
        key = normalize_request_id(request_id)
        record = self._records.get(key)
        if record is None:
            raise UnknownReservationError("unknown request: %r" % (key,))
        return self._copy(record)

    def has_request(self, request_id):
        return normalize_request_id(request_id) in self._records

    def allocated(self, resource_id):
        target = normalize_resource_id(resource_id)
        self._require_resource(target)
        return self._allocated(target)

    def available(self, resource_id):
        target = normalize_resource_id(resource_id)
        self._require_resource(target)
        return self._table.limit_of(target) - self._allocated(target)

    def totals(self):
        return dict((key, self._allocated(key)) for key in self._table.resource_ids())

    def limits(self):
        return self._table.as_dict()

    def resource_ids(self):
        return self._table.resource_ids()

    def request_ids(self):
        return tuple(sorted(self._records))

    def list_reservations(self, resource_id=None, include_released=False):
        target = None
        if resource_id is not None:
            target = normalize_resource_id(resource_id)
        if not isinstance(include_released, bool):
            raise ValidationError("include_released must be a bool")
        if target is not None:
            self._require_resource(target)
        selected = []
        for record in self._records.values():
            if target is not None and record["resource_id"] != target:
                continue
            if not include_released and record["status"] != "active":
                continue
            selected.append(record)
        selected.sort(key=lambda item: (item["created_at"], item["request_id"]))
        return tuple(self._copy(record) for record in selected)

    # -- snapshots ---------------------------------------------------
    def snapshot(self):
        frozen = dict((key, dict(value)) for key, value in self._records.items())
        self._snapshots.append((frozen, self._table.as_dict()))
        return len(self._snapshots)

    def rollback(self, token):
        if isinstance(token, bool) or not isinstance(token, int):
            raise ValidationError("token must be an int")
        if token < 1 or token > len(self._snapshots):
            raise ValidationError("unknown snapshot token: %r" % (token,))
        records, limits = self._snapshots[token - 1]
        self._records = dict((key, dict(value)) for key, value in records.items())
        self._table = CapacityTable(limits)
        return None
